import {graph,change,clone} from './chem-core.mjs';
export function acid(n=4){const atoms=Array.from({length:n},(_,i)=>['C'+(i+1),'C',90+i*85,190+(i%2? -35:0)]);atoms.push(['O1','O',90+(n-1)*85,65],['O2','O',175+(n-1)*85,205]);const bonds=Array.from({length:n-1},(_,i)=>['C'+(i+1),'C'+(i+2),1]);bonds.push(['C'+n,'O1',2],['C'+n,'O2',1]);return graph(atoms,bonds)}
export const butanoic=acid(4),propanoic=acid(3),butanoyl=change(butanoic,{atoms:{O2:{el:'Cl'}}}),propanol=change(propanoic,{bonds:{'C3~O1':1},removeAtoms:['O2']});
export const bromopropane=graph([['C1','C',100,180],['C2','C',190,130],['C3','C',280,180],['Br1','Br',370,130]],[['C1','C2'],['C2','C3'],['C3','Br1']]);
export const butanenitrile=graph([['C1','C',85,180],['C2','C',170,130],['C3','C',255,180],['C4','C',340,130],['N1','N',435,130]],[['C1','C2'],['C2','C3'],['C3','C4'],['C4','N1',3]]);
export const fischerSource=graph([['A_R','C',95,215],['A_C','C',205,160],['A_O','O',205,60,1],['A_H','H',265,40],['A_OH','O',310,215],['M_O','O',405,110],['M_C','C',505,165],['M_H','H',405,45]],[['A_R','A_C'],['A_C','A_O',2],['A_O','A_H'],['A_C','A_OH'],['M_O','M_C'],['M_O','M_H']]);
fischerSource.trackHydrogens=true;
export const fischerAdduct=change(fischerSource,{atoms:{A_O:{charge:0},M_O:{charge:1}},bonds:{'A_C~A_O':1,'A_C~M_O':1}});
export const fischerWater=clone(fischerAdduct);fischerWater.atoms.push({id:'W_O',el:'O',x:550,y:65,charge:0,label:'H2O'});
export const fischerDeprot=change(fischerWater,{atoms:{M_O:{charge:0},W_O:{charge:1,label:null}},bonds:{'M_H~M_O':0,'M_H~W_O':1}});
export const hvzSource=graph([['E_R','C',55,225],['E_alpha','C',145,175],['E_BrAlpha','Br',145,70],['E_C','C',240,225],['E_O','O',240,320],['E_BrAcyl','Br',335,170],['N_R','C',600,220],['N_alpha','C',520,170],['N_C','C',520,70],['N_O','O',425,35],['N_OH','O',610,35],['N_H','H',660,75]],[['E_R','E_alpha'],['E_alpha','E_BrAlpha'],['E_alpha','E_C'],['E_C','E_O',2],['E_C','E_BrAcyl'],['N_R','N_alpha'],['N_alpha','N_C'],['N_C','N_O',2],['N_C','N_OH'],['N_OH','N_H']]);
hvzSource.trackHydrogens=true;
export const hvzTetra=change(hvzSource,{atoms:{E_O:{charge:-1},N_O:{charge:1}},bonds:{'E_C~E_O':1,'E_C~N_O':1}});
export const hvzTetraResonance=change(hvzTetra,{atoms:{N_O:{charge:0},N_OH:{charge:1}},bonds:{'N_C~N_O':1,'N_C~N_OH':2}});
export const hvzCollapse=change(hvzTetra,{atoms:{E_O:{charge:0},E_BrAcyl:{charge:-1,x:365,y:300}},bonds:{'E_C~E_O':2,'E_BrAcyl~E_C':0}});
export const hvzCollapseResonance=change(hvzCollapse,{atoms:{N_O:{charge:0},N_OH:{charge:1}},bonds:{'N_C~N_O':1,'N_C~N_OH':2}});
